# Atomically takes an ack waiting entry for the socket so that multiple
# threads cannot process the same response concurrently.
def take(sock)
  @mutex.synchronize do
    info = @ack_waitings.find { |info| info.sock == sock }
    @ack_waitings.delete(info) if info
    info
  end
end

def delete(info)
  @mutex.synchronize do
    @ack_waitings.delete(info)
  end
end

